-- DarkChaos: armor and weapon damage for 337_'s drop ladder (420000-420429)
--
-- 337_ inserted its 430 items with stats but never set `armor` or `dmg_min1`/`dmg_max1`. Measured 11-11: all 340
-- armour pieces (cloth/leather/mail/plate/shield) had armor 0 and all 60 weapons did 0 damage. A weapon with good
-- stats and no damage also looks like an upgrade to playerbots. This sets both from the Cata curve DBCs at each
-- item's own ItemLevel and Quality (weapon speed unchanged) - the same source as the 751 rewards. 400 rows.
-- Re-runnable: absolute values. Apply to acore_world, then restart the worldserver.

CREATE TABLE IF NOT EXISTS `dc_fix_337_armor_dmg` (
    `entry` INT UNSIGNED NOT NULL,
    `armor` INT UNSIGNED NOT NULL,
    `dmg_min1` INT UNSIGNED NOT NULL,
    `dmg_max1` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DELETE FROM `dc_fix_337_armor_dmg`;

UPDATE `item_template` AS `t`
JOIN `dc_fix_337_armor_dmg` AS `x` ON `x`.`entry` = `t`.`entry`
SET `t`.`armor` = `x`.`armor`;

UPDATE `item_template` AS `t`
JOIN `dc_fix_337_armor_dmg` AS `x` ON `x`.`entry` = `t`.`entry`
SET `t`.`dmg_min1` = `x`.`dmg_min1`;

UPDATE `item_template` AS `t`
JOIN `dc_fix_337_armor_dmg` AS `x` ON `x`.`entry` = `t`.`entry`
SET `t`.`dmg_max1` = `x`.`dmg_max1`;
